<?php
require_once 'config.php';
if(!isset($_SESSION['user'])||!in_array($_SESSION['user']['role'],['supervisor','admin'],true))redirect('index.php');
$user=$_SESSION['user'];$isAdmin=$user['role']==='admin';
$perms=['can_approve'=>1,'can_reject'=>1,'can_force_end'=>1,'can_manual_rest'=>1,'can_chat'=>1,'can_view_other_teams'=>1];
if(!$isAdmin){$st=$pdo->prepare("SELECT * FROM supervisor_permissions WHERE supervisor_username=? LIMIT 1");$st->execute([$user['username']]);$p=$st->fetch();if($p)$perms=array_intersect_key($p,$perms);}
$supervisors=$pdo->query("SELECT username,display_name FROM users WHERE role='supervisor' ORDER BY display_name")->fetchAll();
$experts=$pdo->query("SELECT e.username,e.display_name,e.supervisor_username,u.display_name supervisor_name,e.rest_login_count,e.daily_rest_limit,e.last_rest_login_date FROM experts e LEFT JOIN users u ON u.username=e.supervisor_username ORDER BY u.display_name,e.display_name")->fetchAll();foreach($experts as &$e)if($e['last_rest_login_date']!==date('Y-m-d'))$e['rest_login_count']=0;unset($e);
$mine=$isAdmin?$experts:array_values(array_filter($experts,fn($e)=>$e['supervisor_username']===$user['username']));$others=$isAdmin?[]:array_values(array_filter($experts,fn($e)=>$e['supervisor_username']!==$user['username']));
$st=$pdo->prepare("SELECT COUNT(*) FROM rest_requests WHERE status='pending'".($isAdmin?'':" AND supervisor_username=?"));$st->execute($isAdmin?[]:[$user['username']]);$pendingCount=(int)$st->fetchColumn();
$st=$pdo->prepare("SELECT COUNT(*) FROM rest_requests WHERE status='approved'".($isAdmin?'':" AND supervisor_username=?"));$st->execute($isAdmin?[]:[$user['username']]);$activeCount=(int)$st->fetchColumn();
?>
