<script>
window.CURRENT_USERNAME=<?=json_encode($user['username'])?>;window.CURRENT_ROLE=<?=json_encode($user['role'])?>;window.IS_ADMIN=<?=$isAdmin?'true':'false'?>;window.PERMS=<?=json_encode($perms)?>;let scope='mine',approveId=0,statusFilter='all';let expertPages={mine:1,other:1};let manageExpertPage=1;const EXPERTS_PER_PAGE=10;
function toggleTheme(){document.body.classList.toggle('light');localStorage.setItem('shaya-theme',document.body.classList.contains('light')?'light':'dark')}if(localStorage.getItem('shaya-theme')==='light')document.body.classList.add('light');
function toast(t){let x=document.createElement('div');x.className='toastx';x.textContent=t;document.body.appendChild(x);setTimeout(()=>x.remove(),3200)}
async function post(u,d={}){let r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(d),credentials:'same-origin',cache:'no-store'});return r.json()}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function setScope(s){scope=s;document.getElementById('mineTab').classList.toggle('active',s==='mine');document.getElementById('otherTab').classList.toggle('active',s==='other');if(s==='mine')document.getElementById('supFilter').value='';refresh()}
function setStatusFilter(v){statusFilter=v;expertPages={mine:1,other:1};document.querySelectorAll('.status-filter').forEach(b=>b.classList.toggle('active',b.dataset.status===v));renderTeams(window._allExperts||[])}
function matchesExpert(e){let q=(document.getElementById('expertSearch')?.value||'').trim().toLowerCase();if(q&&![e.display_name,e.username,e.supervisor_name,e.supervisor_username].some(v=>String(v||'').toLowerCase().includes(q)))return false;if(statusFilter==='resting'&&!e.currently_resting)return false;if(statusFilter==='overlimit'&&!e.over_limit)return false;if(statusFilter==='pending'&&!e.pending_request)return false;return true}
function fmtOver(sec){sec=Math.max(0,Math.floor(+sec||0));let m=Math.floor(sec/60),s=sec%60;return m?`${m} دقیقه${s?` و ${s} ثانیه`:''}`:`${s} ثانیه`}function expertRow(e){let st=e.pending_request?'در انتظار تأیید':(e.over_limit?'استراحت غیر مجاز':(e.currently_resting?'در حال استراحت':'آنلاین'));let cls=e.pending_request?'warn':(e.over_limit?'danger':(e.currently_resting?'ok':''));let card=e.pending_request?'status-pending':(e.over_limit?'status-over':(e.currently_resting?'status-resting':'status-online'));let over=(e.over_limit&&+e.over_limit_seconds>0)?`<div class=\"muted over-detail\" style=\"font-size:12px;margin-top:6px\">⚠ میزان تخلف: ${esc(fmtOver(e.over_limit_seconds))}</div>`:'';return `<div class=\"request expert-card ${card}\" style=\"display:block\"><div class=\"row\"><b>${esc(e.display_name)}</b><span class=\"pill ${cls}\">${esc(st)}</span></div>${over}<div class=\"row expert-meta\"><span class=\"muted\">${esc(e.supervisor_name||e.supervisor_username)}</span></div></div>`}
function renderManageExperts(ex){const b=document.getElementById('manageExpertsList'),pager=document.getElementById('manageExpertsPager');if(!b||!pager)return;let q=(document.getElementById('manageExpertSearch')?.value||'').trim().toLowerCase();if(q)ex=ex.filter(e=>[e.display_name,e.username,e.supervisor_name,e.supervisor_username].some(v=>String(v||'').toLowerCase().includes(q)));const total=ex.length,pages=Math.max(1,Math.ceil(total/EXPERTS_PER_PAGE));manageExpertPage=Math.min(Math.max(1,manageExpertPage||1),pages);const page=manageExpertPage,start=(page-1)*EXPERTS_PER_PAGE;b.innerHTML=ex.slice(start,start+EXPERTS_PER_PAGE).map(e=>`<tr><td><b>${esc(e.display_name)}</b><div class="muted">${esc(e.username)}</div></td><td>${esc(e.supervisor_name||e.supervisor_username)}</td><td><button class="btnx btn-danger" onclick="deleteExpert('${esc(e.username)}')">حذف</button></td></tr>`).join('')||'<tr><td colspan="3" class="empty">کارشناسی پیدا نشد.</td></tr>';if(total<=EXPERTS_PER_PAGE){pager.innerHTML='';return;}pager.innerHTML=`<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-top:12px;font-size:12px"><span class="muted">${start+1} تا ${Math.min(start+EXPERTS_PER_PAGE,total)} از ${total} کارشناس</span><div style="display:flex;gap:6px;align-items:center"><button class="btnx" ${page===1?'disabled':''} onclick="changeManageExpertPage(${page-1})">قبلی</button><span class="muted">صفحه ${page} از ${pages}</span><button class="btnx" ${page===pages?'disabled':''} onclick="changeManageExpertPage(${page+1})">بعدی</button></div></div>`}function changeManageExpertPage(page){manageExpertPage=page;renderManageExperts(window._allExperts||[])}
async function addExpert(){const d={action:'add',username:document.getElementById('newExpertUser').value.trim(),display_name:document.getElementById('newExpertName').value.trim(),password:document.getElementById('newExpertPass').value,supervisor:document.getElementById('newExpertSup').value};const r=await post('ajax_expert_manage.php',d);toast(r.message||'');if(r.success){document.getElementById('newExpertUser').value='';document.getElementById('newExpertName').value='';document.getElementById('newExpertPass').value='';refresh()}}
async function deleteExpert(u){if(!confirm('این کارشناس و سوابق مربوط به او حذف شود؟'))return;const r=await post('ajax_expert_manage.php',{action:'delete',username:u});toast(r.message||'');if(r.success)refresh()}
function renderExpertPage(list,boxId,pagerId,key){const box=document.getElementById(boxId),pager=document.getElementById(pagerId);if(!box||!pager)return;const total=list.length,pages=Math.max(1,Math.ceil(total/EXPERTS_PER_PAGE));expertPages[key]=Math.min(Math.max(1,expertPages[key]||1),pages);const page=expertPages[key],start=(page-1)*EXPERTS_PER_PAGE;box.innerHTML=list.slice(start,start+EXPERTS_PER_PAGE).map(expertRow).join('')||'<div class="empty">موردی برای نمایش نیست.</div>';if(total<=EXPERTS_PER_PAGE){pager.innerHTML='';return;}pager.innerHTML=`<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-top:12px;font-size:12px"><span class="muted">${start+1} تا ${Math.min(start+EXPERTS_PER_PAGE,total)} از ${total} کارشناس</span><div style="display:flex;gap:6px;align-items:center"><button class="btnx" ${page===1?'disabled':''} onclick="changeExpertPage('${key}',${page-1})">قبلی</button><span class="muted">صفحه ${page} از ${pages}</span><button class="btnx" ${page===pages?'disabled':''} onclick="changeExpertPage('${key}',${page+1})">بعدی</button></div></div>`}function changeExpertPage(key,page){expertPages[key]=page;renderTeams(window._allExperts||[])}function renderTeams(ex){window._allExperts=ex;let m=document.getElementById('mineExperts'),o=document.getElementById('otherExperts');if(!m||!o)return;let filter=document.getElementById('supFilter').value;let mine=ex.filter(x=>x.supervisor_username===CURRENT_USERNAME&&matchesExpert(x));let others=ex.filter(x=>x.supervisor_username!==CURRENT_USERNAME&&(scope==='other'||CURRENT_ROLE==='admin')&&matchesExpert(x));if(filter)others=others.filter(x=>x.supervisor_username===filter);renderExpertPage(mine,'mineExperts','minePager','mine');renderExpertPage(others,'otherExperts','otherPager','other');renderManualExperts()}
function renderPending(a){let b=document.getElementById('pendingList');document.getElementById('queueCount').textContent=a.length+' نفر';b.innerHTML=a.length?a.map((r,i)=>`<div class="qitem ${r.request_type==='emergency'?'emergency-q':''}"><div class="qnum">${i+1}</div><div style="flex:1"><b>${esc(r.expert_name||r.expert_username)}</b><div class="request-type-label ${r.request_type==='emergency'?'emergency-type':'normal-type'}">${r.request_type==='emergency'?'🚨 درخواست اضطراری':'☕ درخواست عادی'}</div><div class="status-live-label live-pending-label">در انتظار تأیید</div><div class="muted" style="font-size:11px;margin-top:4px">${esc(r.supervisor_name||'')}</div></div><div class="actions" style="margin:0">${(PERMS.can_approve||IS_ADMIN)?`<button class="btnx btn-success" onclick="approve(${r.id})">تأیید</button>`:''}${(PERMS.can_reject||IS_ADMIN)?`<button class="btnx btn-danger" onclick="rejectReq(${r.id})">رد/لغو</button>`:''}</div></div>`).join(''):'<div class="empty">صف خالی است.</div>'}
function renderActive(a){let b=document.getElementById('activeList');document.getElementById('activeBadge').textContent=a.length;b.innerHTML=a.length?a.map(r=>`<div class="request active ${r.request_type==='emergency'?'emergency-active':''}" data-request-id="${r.id}"><div class="row"><b>${esc(r.expert_name||r.expert_username)}</b><span class="pill ok timer" data-start="${r.approved_ts||0}" data-duration="${r.duration_minutes}">--:--</span></div><div class="request-type-label ${r.request_type==='emergency'?'emergency-type':'normal-type'}">${r.request_type==='emergency'?'🚨 درخواست اضطراری':'☕ درخواست عادی'}</div><div class="status-live-label live-rest-label live-state-label">در حال استراحت</div><div class="muted" style="font-size:12px;margin-top:7px">${esc(r.supervisor_name||'')} • ${r.duration_minutes} دقیقه</div>${(PERMS.can_force_end||IS_ADMIN)?`<button class="btnx btn-danger" style="margin-top:9px" onclick="forceEnd(${r.id})">پایان دستی</button>`:''}</div>`).join(''):'<div class="empty">استراحت فعالی نیست.</div>';tickTimers()}
function tickTimers(){document.querySelectorAll('.timer').forEach(t=>{let duration=(+t.dataset.duration||0)*60;let start=(+t.dataset.start||0)*1000;let rem=duration-Math.floor((Date.now()-start)/1000);let card=t.closest('.request');let label=card?.querySelector('.live-state-label');if(rem>=0){t.textContent=String(Math.floor(rem/60)).padStart(2,'0')+':'+String(rem%60).padStart(2,'0');card?.classList.remove('status-over');card?.classList.add('status-resting');if(label){label.textContent='در حال استراحت';label.className='status-live-label live-rest-label live-state-label'}}else{let x=-rem;t.textContent='+'+String(Math.floor(x/60)).padStart(2,'0')+':'+String(x%60).padStart(2,'0');card?.classList.remove('status-resting');card?.classList.add('status-over');if(label){label.textContent='استراحت غیر مجاز';label.className='status-live-label live-over-label live-state-label'}}})}setInterval(tickTimers,1000);
async function approve(id){approveId=id;document.getElementById('approveModal').classList.remove('hidden')}function closeApprove(){document.getElementById('approveModal').classList.add('hidden')}async function confirmApprove(){let r=await post('ajax_approve_rest.php',{request_id:approveId,duration:document.getElementById('approveDuration').value});toast(r.message||'');if(r.success){closeApprove();refresh()}}async function rejectReq(id){if(!confirm('این درخواست رد شود؟'))return;let r=await post('ajax_reject_rest.php',{request_id:id});toast(r.message||'');if(r.success)refresh()}async function forceEnd(id){if(!confirm('استراحت پایان داده شود؟'))return;let r=await post('ajax_end_rest.php',{request_id:id});toast(r.message||'');if(r.success)refresh()}function renderManualExperts(){const sel=document.getElementById('manualExpert'),sup=document.getElementById('manualSupFilter')?.value||'';if(!sel)return;const prev=sel.value;const arr=(window._allExperts||[]).filter(e=>!sup||e.supervisor_username===sup);sel.innerHTML='<option value="">انتخاب کارشناس</option>'+arr.map(e=>`<option value="${esc(e.username)}">${esc(e.display_name)}</option>`).join('');if(arr.some(e=>e.username===prev))sel.value=prev;}
async function manualRest(){let e=document.getElementById('manualExpert').value;if(!e)return toast('کارشناس را انتخاب کنید.');let r=await post('ajax_manual_rest.php',{expert:e,duration:document.getElementById('manualDuration').value});toast(r.message||'');if(r.success)refresh()}
let lastPendingIds=new Set();let alertsInitialized=false;let alarmCtx=null;let alertQueue=[];let alertBusy=false;
function unlockAlerts(){
  try{alarmCtx=alarmCtx||new (window.AudioContext||window.webkitAudioContext)();if(alarmCtx.state==='suspended')alarmCtx.resume();}catch(e){}
  if('Notification' in window && Notification.permission==='default'){try{Notification.requestPermission().catch(()=>{});}catch(e){}}
}
['pointerdown','keydown','touchstart'].forEach(ev=>document.addEventListener(ev,unlockAlerts,{once:true,passive:true}));
function beepAlert(){try{if(!alarmCtx)unlockAlerts();if(!alarmCtx)return;let now=alarmCtx.currentTime;for(let i=0;i<3;i++){let o=alarmCtx.createOscillator(),g=alarmCtx.createGain();o.type='sine';o.frequency.value=i%2?660:980;g.gain.setValueAtTime(.0001,now+i*.42);g.gain.exponentialRampToValueAtTime(.18,now+i*.42+.02);g.gain.exponentialRampToValueAtTime(.0001,now+i*.42+.28);o.connect(g);g.connect(alarmCtx.destination);o.start(now+i*.42);o.stop(now+i*.42+.3)}}catch(e){}}
function closeRequestAlert(){document.getElementById('requestAlertOverlay')?.classList.add('hidden');alertBusy=false;showNextRequestAlert();}
function showNextRequestAlert(){if(alertBusy||!alertQueue.length)return;let x=alertQueue.shift();alertBusy=true;let emergency=x.request_type==='emergency';document.getElementById('requestAlertIcon').textContent=emergency?'🚨':'🔔';document.getElementById('requestAlertTitle').textContent=emergency?'درخواست استراحت اضطراری':'درخواست استراحت جدید';document.getElementById('requestAlertBody').textContent=(x.expert_name||x.expert_username)+(emergency?' درخواست استراحت اضطراری داده است.':' درخواست استراحت داده است.');document.getElementById('requestAlertOverlay').classList.remove('hidden');}
function notifyNewRequests(items){
  const current=new Set((items||[]).map(x=>+x.id));
  if(!alertsInitialized){lastPendingIds=current;alertsInitialized=true;return;}
  const fresh=(items||[]).filter(x=>!lastPendingIds.has(+x.id));
  if(fresh.length){
    fresh.forEach(x=>alertQueue.push(x));
    beepAlert();
    toast(fresh.length===1?'درخواست استراحت جدید ثبت شد.':'چند درخواست استراحت جدید ثبت شد.');
    if('Notification' in window && Notification.permission==='granted'){fresh.forEach(x=>{try{new Notification(x.request_type==='emergency'?'🚨 درخواست اضطراری':'🔔 درخواست استراحت',{body:(x.expert_name||x.expert_username)+(x.request_type==='emergency'?' درخواست اضطراری داده است.':' درخواست داده است.')});}catch(e){}});}
    showNextRequestAlert();
  }
  lastPendingIds=current;
}
async function loadAnnouncement(){try{let r=await post('ajax_announcement.php',{action:'get'});let a=r.announcement;let box=document.getElementById('currentAnnouncement'),top=document.getElementById('globalAnnouncement');if(!a||!String(a.message||'').trim()){box?.classList.add('hidden');top?.classList.add('hidden');return;}if(box){box.classList.remove('hidden');box.innerHTML='<b>اطلاعیه فعلی:</b><div class="announcement-text">'+esc(a.message)+'</div><div class="muted">'+esc((a.created_by_name||a.created_by)+' • '+a.created_at)+'</div>';}if(top){top.classList.remove('hidden');document.getElementById('globalAnnouncementText').textContent=a.message;document.getElementById('globalAnnouncementMeta').textContent=(a.created_by_name||a.created_by)+' • '+a.created_at;}}catch(e){}}
async function saveAnnouncement(){let msg=document.getElementById('announcementInput').value.trim();if(!msg)return toast('متن اطلاعیه را وارد کنید.');let r=await post('ajax_announcement.php',{action:'save',message:msg});toast(r.message||'');if(r.success){document.getElementById('announcementInput').value='';loadAnnouncement()}}
async function clearAnnouncement(){let r=await post('ajax_announcement.php',{action:'clear'});toast(r.message||'');if(r.success)loadAnnouncement()}
loadAnnouncement();setInterval(loadAnnouncement,5000);
async function refresh(){try{let r=await post('ajax_dashboard.php',{scope,filter_supervisor:document.getElementById('supFilter')?.value||''});if(!r.success)return;document.getElementById('sTotal').textContent=r.stats.total;document.getElementById('sPending').textContent=r.stats.pending;document.getElementById('sActive').textContent=r.stats.active;document.getElementById('sOvertime').textContent=r.stats.over_limit_count??0;renderPending(r.pending);notifyNewRequests(r.pending);renderActive(r.active);renderTeams(r.experts);renderManageExperts(r.experts)}catch(e){}}
async function loadPerms(){let r=await post('ajax_permissions_list.php');if(!r.success)return;let b=document.getElementById('permTable');b.innerHTML=r.items.map(x=>{let fs=['can_approve','can_reject','can_force_end','can_manual_rest','can_chat','can_view_other_teams'];return `<tr><td><b>${esc(x.display_name)}</b><div class="muted">${esc(x.username)}</div></td>`+fs.map(f=>`<td><input type="checkbox" id="${f}_${esc(x.username)}" ${+x[f]?'checked':''}></td>`).join('')+`<td><button class="btnx btn-primary" onclick="savePerm('${esc(x.username)}')">ذخیره</button></td></tr>`}).join('')}
async function savePerm(s){let d={supervisor:s};['can_approve','can_reject','can_force_end','can_manual_rest','can_chat','can_view_other_teams'].forEach(f=>d[f]=document.getElementById(f+'_'+s).checked?'1':'0');let r=await post('ajax_admin_permissions.php',d);toast(r.message||'');if(r.success)loadPerms()}function exportExcel(){const from=pickerValue('fromPicker'),to=pickerValue('toPicker');if(!from||!to)return toast('بازه تاریخ را انتخاب کنید.');if(from>to)return toast('تاریخ شروع نباید بعد از تاریخ پایان باشد.');location.href='export_excel.php?from='+encodeURIComponent(from)+'&to='+encodeURIComponent(to)}
function makePicker(id,defaultDate){const box=document.getElementById(id);if(!box)return;let y=defaultDate[0],m=defaultDate[1],d=defaultDate[2];let ys='';for(let i=y-2;i<=y+2;i++)ys+=`<option value="${i}" ${i===y?'selected':''}>${faDigits(String(i))}</option>`;let ms=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];box.innerHTML=`<select class="select jy">${ys}</select><select class="select jm">${ms.map((x,i)=>`<option value="${i+1}" ${i+1===m?'selected':''}>${x}</option>`).join('')}</select><select class="select jd"></select>`;let yd=box.querySelector('.jy'),md=box.querySelector('.jm'),dd=box.querySelector('.jd');function fill(){let max=md.value<=6?31:(md.value<=11?30:29);dd.innerHTML=Array.from({length:max},(_,i)=>`<option value="${i+1}" ${i+1===d?'selected':''}>${faDigits(String(i+1))}</option>`).join('');d=Math.min(d,max)}yd.onchange=()=>{};md.onchange=()=>{d=1;fill()};fill()}
function pickerValue(id){const b=document.getElementById(id);if(!b)return '';let y=b.querySelector('.jy').value,m=String(b.querySelector('.jm').value).padStart(2,'0'),d=String(b.querySelector('.jd').value).padStart(2,'0');return `${y}/${m}/${d}`}
function faDigits(s){return String(s).replace(/[0-9]/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d])}
const todayJ=<?=json_encode(gregorianToJalali((int)date('Y'),(int)date('n'),(int)date('j')))?>;const fromJ=[todayJ[0],todayJ[1],Math.max(1,todayJ[2]-7)];makePicker('fromPicker',fromJ);makePicker('toPicker',todayJ);
if(IS_ADMIN)loadPerms();refresh();setInterval(refresh,1000);
</script></body></html>
